def count_unique_shifts(s: str, first_letter: str) -> int:
    count = 0
    n = len(s)
    for i in range(n):
        if s[i] == first_letter:
            count += 1
    return count

def calculate_probability(s: str) -> float:
    n = len(s)
    unique_shifts = 0
    for first_letter in set(s):
        unique_shifts += count_unique_shifts(s, first_letter)
    return unique_shifts / n
